	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void defaultOpenClosePreservesLegacyMarker(boolean versionMarkerPresent) throws Exception {
		LmdbCompatibilityFixtures.extract("v2-610-default.zip", directory);
		byte[] expected = versionMarkerPresent ? new byte[] { 1 } : null;
		LmdbCompatibilityFixtures.nativePut(directory, "ref_counts", new byte[] { 0 }, expected);

		for (int reopen = 0; reopen < 2; reopen++) {
			SailRepository repository = new SailRepository(new LmdbStore(directory.toFile(), new LmdbStoreConfig()));
			repository.init();
			try (var connection = repository.getConnection()) {
				assertThat(connection.size()).isPositive();
			} finally {
				repository.shutDown();
			}
			byte[] actual = LmdbCompatibilityFixtures.nativeGet(directory, "ref_counts", new byte[] { 0 });
			assertThat(actual).as("opening a legacy store must preserve the earlier reader's marker")
					.isEqualTo(expected);
			assertEarlierReferenceCountReaderAccepts(actual);
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void disabledRepairPreservesDeletionRollbackAndDeferredReclamation(boolean snapshot) throws Exception {
		LmdbCompatibilityFixtures.extract("v2-610-default.zip", directory);
		var vf = SimpleValueFactory.getInstance();
		var subject = vf.createIRI("urn:legacy-repair:subject");
		var predicate = vf.createIRI("urn:legacy-repair:predicate");
		var literal = vf.createLiteral("dictionary value awaiting legacy reference-count repair");
		var isolation = snapshot ? IsolationLevels.SNAPSHOT : IsolationLevels.NONE;
		long literalId;
		LmdbStore store = durableStore(false);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try (var connection = repository.getConnection()) {
			connection.begin(isolation);
			connection.add(subject, predicate, literal);
			connection.commit();
			literalId = ((ValueStore) store.getValueFactory()).getId(literal);
			connection.begin(isolation);
			connection.remove(subject, predicate, literal);
			connection.rollback();
			assertThat(connection.hasStatement(subject, predicate, literal, false)).isTrue();
			connection.begin(isolation);
			connection.remove(subject, predicate, literal);
			connection.commit();
			assertThat(connection.hasStatement(subject, predicate, literal, false)).isFalse();
			assertThat(((ValueStore) store.getValueFactory()).getId(literal)).isEqualTo(literalId);
			// This contract follows durable retirement intents through offline repair and a held post-ready gate.
			assertThat(store.getBackingStore().valueStore().hasRetiredIds()).isTrue();
		} finally {
			repository.shutDown();
		}
		assertThat(LmdbCompatibilityFixtures.nativeGet(directory, null, LmdbCompatibilityFixtures.idKey(literalId)))
				.as("unverified counts cannot authorize physical deletion")
				.isNotNull();
		assertThat(LmdbCompatibilityFixtures.nativeGet(directory, "ref_counts", new byte[] { 0 })).isNull();

		store = durableStore(false);
		repository = new SailRepository(store);
		repository.init();
		try (var connection = repository.getConnection()) {
			assertThat(connection.hasStatement(subject, predicate, literal, false)).isFalse();
			assertThat(((ValueStore) store.getValueFactory()).getId(literal)).isEqualTo(literalId);
		} finally {
			repository.shutDown();
		}

		store = durableStore(true);
		repository = new SailRepository(store);
		repository.init();
		try (var connection = repository.getConnection()) {
			assertThat(connection.hasStatement(subject, predicate, literal, false)).isFalse();
			assertThat(((ValueStore) store.getValueFactory()).getId(literal)).isEqualTo(literalId);
			assertThat(store.getBackingStore().valueStore().hasTrustedReferenceCounts()).isFalse();
		} finally {
			repository.shutDown();
		}
		LmdbStore.reconstructReferenceCountsOffline(directory.toFile(),
				new LmdbStoreConfig().setLegacyReferenceCountRepairEnabled(true));
		store = storeWithPostReadyGateHeld(true);
		repository = new SailRepository(store);
		repository.init();
		try (var connection = repository.getConnection()) {
			assertThat(connection.hasStatement(subject, predicate, literal, false)).isFalse();
			assertThat(store.getBackingStore().valueStore().hasTrustedReferenceCounts()).isTrue();
			assertThat(store.getBackingStore().valueStore().hasRetiredIds()).isTrue();
			assertThat(((ValueStore) store.getValueFactory()).getId(literal)).isEqualTo(literalId);
		} finally {
			repository.shutDown();
		}
		assertThat(LmdbCompatibilityFixtures.nativeGet(directory, null, LmdbCompatibilityFixtures.idKey(literalId)))
				.as("explicit count reconstruction retains deferred owners and queues for bounded maintenance")
				.isNotNull();

		repository = new SailRepository(durableStore(false));
		repository.init();
		repository.shutDown();
		assertEarlierReferenceCountReaderAccepts(
				LmdbCompatibilityFixtures.nativeGet(directory, "ref_counts", new byte[] { 0 }));
	}

