	private static byte[] structuredMarker(String state) {
		ByteBuffer marker = ByteBuffer.allocate(18);
		marker.putInt(0x52434654).put((byte) 1).put((byte) (state.equals("dirty") ? 0 : 1)).putLong(123L);
		CRC32 checksum = new CRC32();
		checksum.update(marker.array(), 0, marker.position());
		marker.putInt((int) checksum.getValue() + (state.equals("checksum") ? 1 : 0));
		return marker.array();
	}

	/** The earlier repair reader accepts absence or precisely the one-byte version, before opening any counts. */
	private static void assertEarlierReferenceCountReaderAccepts(byte[] marker) throws IOException {
		if (marker != null && ByteBuffer.wrap(marker).compareTo(ByteBuffer.wrap(new byte[] { 1 })) != 0) {
			throw new IOException("Unsupported LMDB reference-count version");
		}
	}
